import React, { useMemo, useState, useEffect } from "react";
import { User } from "../pages/Users";

interface Column {
  label: string;
  key: keyof User;
}

interface Props {
  data: User[];
  columns: Column[];
  onSort: (key: keyof User) => void;
  sortConfig?: { key: keyof User; direction: "asc" | "desc" } | null;
  rowsPerPage?: number;
  onViewUser?: (user: User) => void;
  onSuspendUser?: (user: User) => void;
}

/* ─── Status ─────────────────────────────────────────────────── */
type Status = "active" | "suspended" | "pending";

function deriveStatus(user: User): Status {
  if (user.location_allowed === true) return "active";
  if (user.location_allowed === false) return "suspended";
  return "pending";
}

const STATUS_STYLES: Record<Status, React.CSSProperties> = {
  active:    { background: "#DCFCE7", color: "#16A34A" },
  suspended: { background: "#FEE2E2", color: "#DC2626" },
  pending:   { background: "#FEF9C3", color: "#CA8A04" },
};

const StatusBadge: React.FC<{ status: Status }> = ({ status }) => (
  <span style={{
    ...STATUS_STYLES[status],
    padding: "3px 12px", borderRadius: 20,
    fontSize: 12, fontWeight: 600, letterSpacing: 0.2, display: "inline-block",
  }}>
    {status.charAt(0).toUpperCase() + status.slice(1)}
  </span>
);

/* ─── Avatar ─────────────────────────────────────────────────── */
const Avatar: React.FC<{ src?: string | null; name: string; size?: number }> = ({ src, name, size = 36 }) => {
  const initials = name.split(" ").map((w) => w[0]).join("").slice(0, 2).toUpperCase();
  return src ? (
    <img src={src} alt={name}
      style={{ width: size, height: size, borderRadius: "50%", objectFit: "cover", border: "2px solid #F1F5F9", flexShrink: 0 }}
      onError={(e) => { (e.currentTarget as HTMLImageElement).style.display = "none"; }}
    />
  ) : (
    <div style={{
      width: size, height: size, borderRadius: "50%", background: "#E2E8F0",
      display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: size * 0.36, fontWeight: 700, color: "#64748B", flexShrink: 0,
    }}>
      {initials || "?"}
    </div>
  );
};

/* ─── Icon button ────────────────────────────────────────────── */
const IconBtn: React.FC<{ title: string; onClick: () => void; children: React.ReactNode }> = ({ title, onClick, children }) => {
  const [hovered, setHovered] = useState(false);
  return (
    <button title={title} onClick={onClick}
      onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
      style={{
        width: 32, height: 32, border: "1.5px solid #E2E8F0", borderRadius: "50%",
        background: hovered ? "#F8FAFC" : "#fff", cursor: "pointer",
        display: "flex", alignItems: "center", justifyContent: "center",
        transition: "background 0.15s", padding: 0,
      }}
    >
      {children}
    </button>
  );
};

/* ─── Sort icon ──────────────────────────────────────────────── */
const SortIcon: React.FC<{ active: boolean; direction?: "asc" | "desc" }> = ({ active, direction }) => (
  <svg width="13" height="13" viewBox="0 0 13 13" fill="none">
    <path d="M6.5 2v9M6.5 2L4 5M6.5 2L9 5"
      stroke={active && direction === "asc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
    <path d="M6.5 11L4 8M6.5 11L9 8"
      stroke={active && direction === "desc" ? "#EA580C" : "#CBD5E1"}
      strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
  </svg>
);

/* ─── Page button ────────────────────────────────────────────── */
const PageBtn: React.FC<{ label: string; active?: boolean; disabled?: boolean; onClick: () => void }> = ({
  label, active = false, disabled = false, onClick,
}) => (
  <button onClick={onClick} disabled={disabled} style={{
    minWidth: 34, height: 34, borderRadius: 8,
    border: active ? "none" : "1px solid #E2E8F0",
    background: active ? "#EA580C" : disabled ? "#F8FAFC" : "#fff",
    color: active ? "#fff" : disabled ? "#CBD5E1" : "#334155",
    fontWeight: 600, fontSize: 13, cursor: disabled ? "not-allowed" : "pointer",
    padding: "0 8px", transition: "background 0.15s",
  }}>
    {label}
  </button>
);

/* ─── Info Row (used in detail panel) ───────────────────────── */
const InfoRow: React.FC<{ label: string; value?: React.ReactNode }> = ({ label, value }) => (
  <div style={{ marginBottom: 14 }}>
    <div style={{ fontSize: 11, fontWeight: 600, color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 3 }}>
      {label}
    </div>
    <div style={{ fontSize: 14, color: value ? "#0F172A" : "#CBD5E1" }}>
      {value || "—"}
    </div>
  </div>
);

/* ─── User Detail Panel ──────────────────────────────────────── */
const UserDetailPanel: React.FC<{ user: User; onClose: () => void; onSuspend?: (u: User) => void }> = ({ user, onClose, onSuspend }) => {
  const status = deriveStatus(user);

  // Lock body scroll when panel is open
  useEffect(() => {
    document.body.style.overflow = "hidden";
    return () => { document.body.style.overflow = ""; };
  }, []);

  return (
    <>
      {/* Backdrop */}
      <div onClick={onClose} style={{
        position: "fixed", inset: 0, background: "rgba(15,23,42,0.35)",
        backdropFilter: "blur(2px)", zIndex: 100,
        animation: "fadeIn 0.2s ease",
      }} />

      {/* Panel */}
      <div style={{
        position: "fixed", top: 0, right: 0, bottom: 0,
        width: "min(480px, 100vw)",
        background: "#fff", zIndex: 101,
        boxShadow: "-8px 0 32px rgba(15,23,42,0.12)",
        display: "flex", flexDirection: "column",
        animation: "slideIn 0.25s ease",
        fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif",
        overflowY: "auto",
      }}>
        {/* Header */}
        <div style={{
          padding: "20px 24px 16px",
          borderBottom: "1px solid #F1F5F9",
          display: "flex", alignItems: "center", justifyContent: "space-between",
          position: "sticky", top: 0, background: "#fff", zIndex: 1,
        }}>
          <h2 style={{ margin: 0, fontSize: 16, fontWeight: 700, color: "#0F172A" }}>User Profile</h2>
          <button onClick={onClose} style={{
            width: 32, height: 32, border: "1px solid #E2E8F0", borderRadius: 8,
            background: "#fff", cursor: "pointer", display: "flex",
            alignItems: "center", justifyContent: "center",
          }}>
            <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
              <path d="M2 2l10 10M12 2L2 12" stroke="#64748B" strokeWidth="1.8" strokeLinecap="round" />
            </svg>
          </button>
        </div>

        {/* Basic Info */}
        <div style={{ padding: "24px", borderBottom: "1px solid #F1F5F9" }}>
          <div style={{ display: "flex", alignItems: "center", gap: 16, marginBottom: 20 }}>
            <Avatar src={user.image_url} name={user.name} size={64} />
            <div>
              <div style={{ fontSize: 18, fontWeight: 700, color: "#0F172A" }}>{user.name || "—"}</div>
              {user.professional_headline && (
                <div style={{ fontSize: 13, color: "#64748B", marginTop: 2 }}>{user.professional_headline}</div>
              )}
              <div style={{ marginTop: 8 }}>
                <StatusBadge status={status} />
              </div>
            </div>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: "0 24px" }}>
            <InfoRow label="Phone" value={user.phone} />
            <InfoRow label="Joined" value={user.created_at ? new Date(user.created_at).toLocaleDateString("en-GB") : undefined} />
            <InfoRow label="Location" value={(user.location_names ?? []).join(", ") || user.location} />
            <InfoRow label="User Types" value={(user.user_type_names ?? []).join(", ")} />
          </div>
        </div>

        {/* About */}
        {user.about_me && (
          <div style={{ padding: "20px 24px", borderBottom: "1px solid #F1F5F9" }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 8 }}>
              About
            </div>
            <p style={{ margin: 0, fontSize: 14, color: "#334155", lineHeight: 1.6 }}>{user.about_me}</p>
          </div>
        )}

        {/* Skills & Certs */}
        <div style={{ padding: "20px 24px", borderBottom: "1px solid #F1F5F9" }}>
          <div style={{ marginBottom: 16 }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 8 }}>
              Skills
            </div>
            {user.skills_id?.length > 0 ? (
              <div style={{ display: "flex", flexWrap: "wrap", gap: 6 }}>
                {user.skills_id.map((s, i) => (
                  <span key={i} style={{
                    padding: "4px 10px", borderRadius: 20, fontSize: 12,
                    background: "#F1F5F9", color: "#475569", fontWeight: 500,
                  }}>{s}</span>
                ))}
              </div>
            ) : <span style={{ fontSize: 14, color: "#CBD5E1" }}>—</span>}
          </div>

          <div>
            <div style={{ fontSize: 12, fontWeight: 600, color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 8 }}>
              Certifications
            </div>
            {user.certifications?.length > 0 ? (
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {user.certifications.map((c, i) => (
                  <div key={i} style={{ fontSize: 14, color: "#334155", display: "flex", alignItems: "center", gap: 6 }}>
                    <span style={{ color: "#EA580C" }}>✦</span> {c}
                  </div>
                ))}
              </div>
            ) : <span style={{ fontSize: 14, color: "#CBD5E1" }}>—</span>}
          </div>
        </div>

        {/* Attachments */}
        {user.profile_attachments?.length > 0 && (
          <div style={{ padding: "20px 24px", borderBottom: "1px solid #F1F5F9" }}>
            <div style={{ fontSize: 12, fontWeight: 600, color: "#94A3B8", textTransform: "uppercase", letterSpacing: 0.7, marginBottom: 8 }}>
              Attachments
            </div>
            {user.profile_attachments.map((att, i) => (
              <a key={i} href={att} target="_blank" rel="noopener noreferrer"
                style={{ display: "block", fontSize: 13, color: "#EA580C", marginBottom: 4 }}>
                {att}
              </a>
            ))}
          </div>
        )}

        {/* Actions */}
        <div style={{ padding: "20px 24px", marginTop: "auto", display: "flex", gap: 10 }}>
          <button onClick={() => onSuspend?.(user)} style={{
            flex: 1, padding: "10px 0", borderRadius: 10, border: "1.5px solid #FEE2E2",
            background: "#FFF5F5", color: "#DC2626", fontWeight: 600, fontSize: 14,
            cursor: "pointer", fontFamily: "inherit",
          }}>
            {status === "suspended" ? "Unsuspend User" : "Suspend User"}
          </button>
          <button onClick={onClose} style={{
            flex: 1, padding: "10px 0", borderRadius: 10, border: "none",
            background: "#0F172A", color: "#fff", fontWeight: 600, fontSize: 14,
            cursor: "pointer", fontFamily: "inherit",
          }}>
            Close
          </button>
        </div>
      </div>

      <style>{`
        @keyframes fadeIn { from { opacity: 0 } to { opacity: 1 } }
        @keyframes slideIn { from { transform: translateX(100%) } to { transform: translateX(0) } }
      `}</style>
    </>
  );
};

/* ─── Mobile Card ────────────────────────────────────────────── */
const MobileUserCard: React.FC<{ user: User; index: number; onClick: () => void }> = ({ user, index, onClick }) => {
  const status = deriveStatus(user);
  return (
    <div onClick={onClick} style={{
      padding: "14px 16px", borderBottom: "1px solid #F1F5F9",
      display: "flex", alignItems: "center", gap: 12,
      cursor: "pointer", transition: "background 0.12s",
      background: "#fff",
    }}
      onMouseEnter={(e) => { e.currentTarget.style.background = "#FAFBFC"; }}
      onMouseLeave={(e) => { e.currentTarget.style.background = "#fff"; }}
    >
      <div style={{ fontSize: 12, color: "#94A3B8", width: 28, flexShrink: 0, textAlign: "center" }}>
        {String(index).padStart(2, "0")}
      </div>
      <Avatar src={user.image_url} name={user.name} size={40} />
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{ fontWeight: 600, fontSize: 14, color: "#0F172A", whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
          {user.name || "—"}
        </div>
        {user.professional_headline && (
          <div style={{ fontSize: 11, color: "#94A3B8", marginTop: 1, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>
            {user.professional_headline}
          </div>
        )}
        {user.location && (
          <div style={{ fontSize: 11, color: "#64748B", marginTop: 2 }}>{user.location}</div>
        )}
      </div>
      <div style={{ flexShrink: 0, display: "flex", flexDirection: "column", alignItems: "flex-end", gap: 6 }}>
        <StatusBadge status={status} />
        <svg width="14" height="14" viewBox="0 0 14 14" fill="none">
          <path d="M5 3l4 4-4 4" stroke="#CBD5E1" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
      </div>
    </div>
  );
};

/* ─── Main ───────────────────────────────────────────────────── */
export const UserTable: React.FC<Props> = ({
  data, columns, onSort, sortConfig,
  rowsPerPage = 10,
  onViewUser, onSuspendUser,
}) => {
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [isMobile, setIsMobile] = useState(false);

  // Detect mobile
  useEffect(() => {
    const mq = window.matchMedia("(max-width: 768px)");
    setIsMobile(mq.matches);
    const handler = (e: MediaQueryListEvent) => setIsMobile(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const totalPages = Math.max(1, Math.ceil(data.length / rowsPerPage));

  const paginatedData = useMemo(() => {
    const start = (currentPage - 1) * rowsPerPage;
    return data.slice(start, start + rowsPerPage);
  }, [data, currentPage, rowsPerPage]);

  const allSelected = paginatedData.length > 0 && paginatedData.every((u) => selectedIds.has(u.id));

  const toggleAll = () =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allSelected) paginatedData.forEach((u) => next.delete(u.id));
      else paginatedData.forEach((u) => next.add(u.id));
      return next;
    });

  const toggleOne = (id: string) =>
    setSelectedIds((prev) => {
      const next = new Set(prev);
      next.has(id) ? next.delete(id) : next.add(id);
      return next;
    });

  const pageNumbers = useMemo(() => {
    if (totalPages <= 5) return Array.from({ length: totalPages }, (_, i) => i + 1);
    if (currentPage <= 3) return [1, 2, 3, 4, 5];
    if (currentPage >= totalPages - 2)
      return [totalPages - 4, totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
    return [currentPage - 2, currentPage - 1, currentPage, currentPage + 1, currentPage + 2];
  }, [currentPage, totalPages]);

  const sortTh = (key: keyof User, label: string) => (
    <th style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(key)}>
      <div style={thInner}>{label}<SortIcon active={sortConfig?.key === key} direction={sortConfig?.key === key ? sortConfig.direction : undefined} /></div>
    </th>
  );

  const handleRowClick = (user: User) => setSelectedUser(user);

  return (
    <>
      <div style={{
        fontFamily: "'DM Sans', 'Helvetica Neue', sans-serif",
        width: "100%", display: "flex", flexDirection: "column",
        background: "#fff", borderRadius: 16,
        border: "1px solid #E8EDF2",
        boxShadow: "0 1px 4px rgba(15,23,42,0.06)",
        overflow: "hidden",
      }}>

        {/* ── MOBILE CARD VIEW ── */}
        {isMobile ? (
          <>
            {paginatedData.length === 0 ? (
              <div style={{ padding: "48px 0", textAlign: "center", color: "#94A3B8", fontSize: 14 }}>
                No users found
              </div>
            ) : paginatedData.map((user, idx) => (
              <MobileUserCard
                key={user.id}
                user={user}
                index={(currentPage - 1) * rowsPerPage + idx + 1}
                onClick={() => handleRowClick(user)}
              />
            ))}
          </>
        ) : (
          /* ── DESKTOP TABLE VIEW ── */
          <div style={{ overflowX: "auto", width: "100%" }}>
            <table style={{ width: "100%", borderCollapse: "collapse", minWidth: 760 }}>
              <thead>
                <tr style={{ background: "#F8FAFC" }}>
                  <th style={{ ...thBase, width: 48 }}>
                    <input type="checkbox" checked={allSelected} onChange={toggleAll}
                      style={{ cursor: "pointer", accentColor: "#EA580C" }} />
                  </th>
                  <th style={{ ...thBase, width: 72 }}>Sr. No.</th>
                  {sortTh("name", "Username")}
                  {columns.map((col) => (
                    <th key={String(col.key)} style={{ ...thBase, cursor: "pointer" }} onClick={() => onSort(col.key)}>
                      <div style={thInner}>
                        {col.label}
                        <SortIcon active={sortConfig?.key === col.key} direction={sortConfig?.key === col.key ? sortConfig.direction : undefined} />
                      </div>
                    </th>
                  ))}
                  {sortTh("location_allowed", "Status")}
                  {sortTh("created_at", "Joined Date")}
                  <th style={{ ...thBase, textAlign: "right" }}>Action</th>
                </tr>
              </thead>
              <tbody>
                {paginatedData.length === 0 ? (
                  <tr>
                    <td colSpan={columns.length + 6}
                      style={{ padding: "48px 0", textAlign: "center", color: "#94A3B8", fontSize: 14 }}>
                      No users found
                    </td>
                  </tr>
                ) : paginatedData.map((user, idx) => {
                  const status = deriveStatus(user);
                  const globalIdx = (currentPage - 1) * rowsPerPage + idx + 1;
                  const isSelected = selectedIds.has(user.id);

                  return (
                    <tr key={user.id}
                      onClick={() => handleRowClick(user)}
                      style={{ background: isSelected ? "#FFF7ED" : "#fff", transition: "background 0.12s", cursor: "pointer" }}
                      onMouseEnter={(e) => { if (!isSelected) e.currentTarget.style.background = "#FAFBFC"; }}
                      onMouseLeave={(e) => { e.currentTarget.style.background = isSelected ? "#FFF7ED" : "#fff"; }}
                    >
                      {/* Checkbox — stop propagation so click doesn't open panel */}
                      <td style={tdBase} onClick={(e) => e.stopPropagation()}>
                        <input type="checkbox" checked={isSelected} onChange={() => toggleOne(user.id)}
                          style={{ cursor: "pointer", accentColor: "#EA580C" }} />
                      </td>
                      <td style={{ ...tdBase, color: "#94A3B8", fontSize: 13 }}>{String(globalIdx).padStart(2, "0")}</td>
                      <td style={tdBase}>
                        <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                          <Avatar src={user.image_url} name={user.name} />
                          <div>
                            <div style={{ fontWeight: 600, fontSize: 14, color: "#0F172A" }}>{user.name || "—"}</div>
                            {user.professional_headline && (
                              <div style={{ fontSize: 11, color: "#94A3B8", marginTop: 1 }}>{user.professional_headline}</div>
                            )}
                          </div>
                        </div>
                      </td>
                      {columns.map((col) => {
                        const val = user[col.key];
                        let display: React.ReactNode = <span style={{ color: "#CBD5E1" }}>—</span>;
                        if (val !== null && val !== undefined && val !== "") {
                          if (Array.isArray(val)) display = val.length ? val.join(", ") : display;
                          else if (typeof val === "boolean") display = val ? "Yes" : "No";
                          else display = String(val);
                        }
                        return <td key={String(col.key)} style={{ ...tdBase, color: "#475569" }}>{display}</td>;
                      })}
                      <td style={tdBase}><StatusBadge status={status} /></td>
                      <td style={{ ...tdBase, color: "#475569", whiteSpace: "nowrap" }}>
                        {user.created_at
                          ? new Date(user.created_at).toLocaleDateString("en-GB")
                          : <span style={{ color: "#CBD5E1" }}>—</span>}
                      </td>
                      <td style={{ ...tdBase, textAlign: "right" }} onClick={(e) => e.stopPropagation()}>
                        <div style={{ display: "flex", gap: 8, justifyContent: "flex-end" }}>
                          <IconBtn title="View details" onClick={() => { onViewUser?.(user); setSelectedUser(user); }}>
                            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                              <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                              <path d="M8 7v4" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                              <circle cx="8" cy="5" r="0.75" fill="#94A3B8" />
                            </svg>
                          </IconBtn>
                          <IconBtn
                            title={status === "suspended" ? "Unsuspend user" : "Suspend user"}
                            onClick={() => onSuspendUser?.(user)}
                          >
                            <svg width="16" height="16" viewBox="0 0 16 16" fill="none">
                              <circle cx="8" cy="8" r="7" stroke="#94A3B8" strokeWidth="1.5" />
                              <path d="M3.5 3.5l9 9" stroke="#94A3B8" strokeWidth="1.5" strokeLinecap="round" />
                            </svg>
                          </IconBtn>
                        </div>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* PAGINATION */}
        {totalPages > 1 && (
          <div style={{
            padding: "14px 20px", borderTop: "1px solid #F1F5F9",
            display: "flex", justifyContent: "space-between",
            alignItems: "center", flexWrap: "wrap", gap: 12,
          }}>
            <span style={{ fontSize: 13, color: "#94A3B8" }}>
              Showing {(currentPage - 1) * rowsPerPage + 1}–{Math.min(currentPage * rowsPerPage, data.length)} of {data.length} users
            </span>
            <div style={{ display: "flex", gap: 6, alignItems: "center" }}>
              <PageBtn label="←" disabled={currentPage === 1} onClick={() => setCurrentPage((p) => Math.max(p - 1, 1))} />
              {pageNumbers[0] > 1 && (
                <>
                  <PageBtn label="1" onClick={() => setCurrentPage(1)} />
                  {pageNumbers[0] > 2 && <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>}
                </>
              )}
              {pageNumbers.map((p) => (
                <PageBtn key={p} label={String(p)} active={p === currentPage} onClick={() => setCurrentPage(p)} />
              ))}
              {pageNumbers[pageNumbers.length - 1] < totalPages && (
                <>
                  {pageNumbers[pageNumbers.length - 1] < totalPages - 1 && (
                    <span style={{ padding: "0 4px", color: "#94A3B8" }}>…</span>
                  )}
                  <PageBtn label={String(totalPages)} onClick={() => setCurrentPage(totalPages)} />
                </>
              )}
              <PageBtn label="→" disabled={currentPage === totalPages} onClick={() => setCurrentPage((p) => Math.min(p + 1, totalPages))} />
            </div>
          </div>
        )}
      </div>

      {/* USER DETAIL PANEL */}
      {selectedUser && (
        <UserDetailPanel
          user={selectedUser}
          onClose={() => setSelectedUser(null)}
          onSuspend={(u) => { onSuspendUser?.(u); setSelectedUser(null); }}
        />
      )}
    </>
  );
};

